define(['core/ajax', 'core/notification'], function(Ajax, Notification) {

    function init() {

        const regionMain =
            document.querySelector('#region-main');

        if (!regionMain) {
            return;
        }

        Ajax.call([{methodname: 'local_coursecarousel_get_available_courses', args: {}}])[0]
        .then(response => {

            regionMain.insertAdjacentHTML(
                'afterbegin',
                response.html
            );

        })
        .catch(Notification.exception);
    }

    return {
        init: init
    };
});
